// App Router examples:
// SSG (default if data is static)
export default async function Docs() { return <Markdown />; }

// ISR — revalidate every hour
export const revalidate = 3600;

// SSR — always dynamic
export const dynamic = 'force-dynamic';
export default async function Dashboard() {
  const data = await getUserData(); // uses cookies → dynamic
}

// pages/products/[id].tsx
export async function getStaticProps({ params }) {
  const p = await getProduct(params.id);
  return { props: { p }, revalidate: 60 };
}

// app/products/[id]/page.tsx — same result, less ceremony:
export const revalidate = 60;
export default async function Page({ params }) {
  const p = await getProduct(params.id);
  return <ProductView p={p} />;
}

// app/products/page.tsx — Server Component (default)
export default async function Page() {
  const products = await db.product.findMany(); // direct DB access ✅
  return <List items={products} />;
}

// components/AddToCart.tsx — Client Component
'use client';
export function AddToCart({ productId }) {
  const [added, setAdded] = useState(false);   // state needs 'use client'
  return <button onClick={() => setAdded(true)}>{added ? 'Added ✓' : 'Add'}</button>;
}

// ❌ mismatch: server & client may format times differently
function Clock() {
  return <span>{new Date().toLocaleTimeString()}</span>;
}

// ✅ stable first render, update after mount
function SafeClock() {
  const [now, setNow] = useState(null);
  useEffect(() => setNow(new Date().toLocaleTimeString()), []);
  return <span suppressHydrationWarning>{now ?? '--:--:--'}</span>;
}

// Cached 60s, tagged for targeted invalidation:
const res = await fetch(`${API}/products`, {
  next: { revalidate: 60, tags: ['products'] },
});

// Somewhere handling a mutation:
import { revalidateTag } from 'next/cache';
revalidateTag('products'); // only product queries refetch

// components/LikeButton.tsx
'use client';
import { useState } from 'react';

export function LikeButton({ count }: { count: number }) {
  const [likes, setLikes] = useState(count);
  return <button onClick={() => setLikes(likes + 1)}>♥ {likes}</button>; // needs client
}

// app/post/page.tsx — stays server:
// <article><LikeButton count={post.likes} /></article>

// app/products/[slug]/page.tsx
export async function generateMetadata({ params }) {
  const product = await getProduct(params.slug);
  return {
    title: `${product.name} — Specs & Reviews`,
    description: product.excerpt,
    alternates: { canonical: `/products/${product.slug}` },
    openGraph: {
      title: product.name,
      images: [product.image],
      type: 'website',
    },
  };
}
